import {escapeHtml as e} from './inventory.mjs';
import {bytes,storageReconciliation} from './usage.mjs';
import {nasStorageInfo} from './nas.mjs';
const time=value=>new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(value));
const kv=rows=>`<dl class="usage-kv">${rows.map(([key,value])=>`<div><dt>${e(key)}</dt><dd>${e(value||'未取得')}</dd></div>`).join('')}</dl>`;
const note=text=>`<p class="usage-note">${e(text)}</p>`;
const branch=(name,count,body,open=false)=>`<details class="usage-branch" ${open?'open':''}><summary><span class="branch-title">${e(name)}</span><span class="usage-count">${e(count)}</span></summary><div class="branch-content">${body}</div></details>`;
const resourceTable=(headings,rows)=>`<div class="resource-scroll"><table class="resource-table"><thead><tr>${headings.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${e(v==null||v===''?'未取得':v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const disks=items=>items.length?items.map(d=>kv([['虛擬磁碟',d.fileName],['主機實際占用',bytes(d.allocatedBytes)],['VHD 檔案長度',bytes(d.fileBytes)]])).join(''):note('未找到可讀取的 VHDX 檔案。');
function controls(pc,kind){return `<div class="usage-actions"><button class="button" data-usage-help="${kind}">${kind==='storage'?'＋ 擷取新快照':'↻ 更新盤點'}</button><button class="button" data-usage-export="${kind}">↓ 匯出${kind==='storage'?'快照':'盤點'}</button></div>`;}
function empty(pc,kind){return `<div class="usage-empty"><span>▤</span><h3>${kind==='storage'?'尚未建立儲存空間快照':'尚未盤點子系統'}</h3><p>${kind==='storage'?'擷取磁碟與資料夾使用量後，可在此逐層展開。':'盤點這台電腦的 WSL 發行版、Docker 引擎、容器與 Images。'}</p><button class="button primary" data-usage-help="${kind}">${kind==='storage'?'擷取第一份快照':'盤點 WSL / Docker'}</button></div>`;}
function expansionNote(snapshot){return snapshot.expandThresholdBytes?note(`本次依 ${bytes(snapshot.expandThresholdBytes)} 門檻保留深層明細：達門檻的資料夾持續往下，達門檻的單一檔案列出名稱；${snapshot.optionalDetailLevels?'較小資料夾也可手動展開已保留的子層，優先保留較大項目。':'較小分支保留合計。'}`):'';}
export function mountStorage(panel,pc){
  const snapshots=pc.storageSnapshots??[];
  if(!snapshots.length){panel.innerHTML=empty(pc,'storage');return;}
  let selected=snapshots.at(-1),nodes=new Map(),nextId=0;
  function row(node,parentBytes){
    const id=String(nextId++);nodes.set(id,node);
    const ratio=parentBytes?Math.min(100,(node.bytes??0)/parentBytes*100):0;
    const label=node.name==='[smaller folders / files]'?'較小檔案與資料夾合計':node.name==='[files / deeper folders]'?'此層檔案與未列出資料夾':node.name;
    const symbol=node.kind==='file'?'▤':node.children.length?'▱':'·';
    const body=`<span class="folder-name"><span class="folder-symbol">${symbol}</span>${e(label)}</span><span class="folder-percent"><i style="width:${ratio}%"></i></span><span class="folder-bytes">${bytes(node.bytes)}</span>`;
    if(node.children.length)return `<details class="folder-node" data-node="${id}"><summary>${body}</summary><div class="folder-children" data-loaded="false"></div></details>`;
    const detail=node.kind==='file'?'檔案':node.truncated?(selected.expandThresholdBytes&&node.bytes<selected.expandThresholdBytes?(selected.optionalDetailLevels?'更深層明細未保留':'低於展開門檻，已合計'):node.kind==='aggregate'?'較小項目已合計':'更深層已合計'):'';
    return `<div class="folder-leaf">${body}${detail?`<small class="depth-note">${detail}</small>`:''}${node.partial?'<small class="depth-note">部分掃描</small>':''}${node.errors?'<small class="depth-note">部分項目無法讀取</small>':''}</div>`;
  }
  function render(){nodes=new Map();nextId=0;
    const physical=selected.volumes.filter(v=>v.physical),total=physical.reduce((sum,v)=>sum+(v.sizeBytes??0),0),used=physical.reduce((sum,v)=>sum+(v.usedBytes??0),0),free=physical.reduce((sum,v)=>sum+(v.freeBytes??0),0);
    panel.innerHTML=`<div class="usage-heading"><div><h3>儲存空間快照</h3><p>磁碟 → 資料夾，點擊箭頭逐層展開。</p></div>${controls(pc,'storage')}</div><div class="usage-snapshot-picker"><label for="storageSnapshot">快照時間</label><select id="storageSnapshot">${snapshots.slice().reverse().map(s=>`<option value="${e(s.id)}" ${s.id===selected.id?'selected':''}>${e(time(s.capturedAt))} (台北)</option>`).join('')}</select><button class="button" id="collapseStorage">全部收合</button></div><div class="usage-metrics">${[['實體磁碟區總量',bytes(total)],['已使用',bytes(used)],['可用空間',bytes(free)]].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div>${nasStorageInfo(pc,selected)}${expansionNote(selected)}<div class="usage-tree">${selected.volumes.map(v=>{const tree=v.tree,reconciliation=storageReconciliation(v);const percent=v.sizeBytes?Math.min(100,100*(v.usedBytes??0)/v.sizeBytes):0;return `<details class="volume-node"><summary><span class="volume-name">▤ <b>${e(v.drive)}</b> <small>${e(v.fileSystem)}</small></span><span class="usage-state ${v.status==='partial'?'partial':''}">${v.status==='complete'?'可讀項目掃描完成':v.status==='partial'?'部分掃描':'未掃描資料夾'}</span><span class="volume-bytes">${bytes(v.usedBytes)} <small>/ ${bytes(v.sizeBytes)}</small></span></summary><div class="volume-body"><div class="storage-track"><i style="width:${percent}%"></i></div>${note(`系統已使用 ${bytes(v.usedBytes)} · 可用 ${bytes(v.freeBytes)}${v.physical?'':' · 虛擬／無實體分割區對應'}`)}${tree?`${kv([['已掃描可讀檔案（邏輯大小）',bytes(tree.bytes)],['掃描結果',reconciliation.state],...(tree.durationSeconds==null?[]:[['掃描耗時',`${tree.durationSeconds} 秒`]]),[reconciliation.label,bytes(reconciliation.difference)],['檔案 / 資料夾',`${(tree.files??0).toLocaleString()} / ${(tree.directories??0).toLocaleString()}`],['無法讀取 / 略過連結',`${tree.errors??0} / ${tree.skipped??0}`]])}${tree.partial?'<p class="usage-alert">已達本次掃描時間上限，資料夾大小為已掃描部分。</p>':''}${note('檔案邏輯大小與系統實際占用的統計方式不同，差額不等於遺失空間或可回收空間；可能涉及未掃描、權限、略過連結、硬連結、壓縮／稀疏檔案及檔案系統資料。')}<div class="folder-list">${tree.children.length?tree.children.map(c=>row(c,tree.bytes)).join(''):note('此磁碟沒有可展開的資料夾資料。')}</div>`:note('此磁碟僅記錄容量。擷取時加上 --drives 可指定掃描的磁碟區。')}</div></details>`;}).join('')}</div>${note(`快照擷取：${time(selected.capturedAt)} → ${time(selected.completedAt)} (台北)。資料夾容量為可讀檔案的邏輯大小，可能包含硬連結重複計數；與系統實際已用空間不同。略過符號連結與目錄接合點，未掃描或無法讀取的項目不估算大小。`)}`;
    panel.querySelector('#storageSnapshot').onchange=event=>{selected=snapshots.find(s=>s.id===event.target.value);render();};
    panel.querySelector('#collapseStorage').onclick=()=>panel.querySelectorAll('details[open]').forEach(d=>{d.open=false;});
  }
  panel.addEventListener('toggle',event=>{const detail=event.target;if(!detail.matches('.folder-node')||!detail.open)return;const childContainer=detail.querySelector(':scope > .folder-children');if(childContainer.dataset.loaded==='true')return;const node=nodes.get(detail.dataset.node);if(!node)return;childContainer.innerHTML=node.children.map(c=>row(c,node.bytes)).join('');childContainer.dataset.loaded='true';},true);
  render();
}
export function mountSubsystems(panel,pc){
  const inventory=pc.subsystems;if(!inventory){panel.innerHTML=empty(pc,'environments');return;}
  const {wsl,docker:d}=inventory,online=d.status==='available',linuxHost=wsl.status==='not-applicable';
  const status=online?'已連線':d.status==='engine-unavailable'?'引擎未連線':d.status==='remote-context'?'遠端 context 未盤點':'未偵測到 CLI';
  const unavailable='Docker 引擎未連線，無法讀取目前容器、Image、Volume 與快取使用量。啟動 Docker 後可重新盤點。';
  const diskSum=d.disks.reduce((sum,v)=>sum+(v.allocatedBytes??0),0),hasDisk=d.disks.some(v=>v.allocatedBytes!=null);
  const wslBody=wsl.distributions.length?wsl.distributions.map(v=>branch(v.name,`${v.state==='running'?'執行中':'已停止'} · WSL ${v.version??'—'}`,`${kv([['作業系統',v.osName],['OS 資料來源',v.osSource==='os-release'?'/etc/os-release':'WSL 登錄名稱（尚未讀取內部版本）'],['狀態',v.state==='running'?'執行中':'已停止'],['Linux 已使用',v.filesystem?bytes(v.filesystem.usedBytes):'未取得'],['Linux 可用 / 總量',v.filesystem?`${bytes(v.filesystem.freeBytes)} / ${bytes(v.filesystem.sizeBytes)}`:'未取得']])}${disks(v.disks)}${!v.filesystem?note(v.state==='running'?'無法讀取 Linux 檔案系統用量。':'此發行版已停止；主機 VHD 占用可讀取，Linux 內部使用量待啟動後盤點。'):''}`)).join(''):note(wsl.available?'未找到已註冊的 WSL 發行版。':linuxHost?'此主機為 Linux，不適用 WSL。':'此電腦未偵測到 WSL。');
  const summaryNames={'Images':'Images','Containers':'容器','Local Volumes':'Volumes','Build Cache':'建置快取'};
  const usageSummary=d.summary.length?resourceTable(['類型','總數 / 使用中','大小','可回收'],d.summary.map(v=>[summaryNames[v.type]||v.type,`${v.totalCount} / ${v.active}`,v.size,v.reclaimable])):note(online?'沒有可用的 Docker 用量摘要。':unavailable);
  const imageRows=d.images.slice().sort((a,b)=>(b.sizeBytes??-1)-(a.sizeBytes??-1)).map(v=>[`${v.repository}:${v.tag}`,`${v.os||'未取得'}${v.architecture?` / ${v.architecture}`:''}`,v.sizeBytes!=null?bytes(v.sizeBytes):v.size,v.id]);
  const containerRows=d.containers.map(v=>[v.name,v.image,`${v.state} · ${v.status}`,v.size]);
  const dockerBody=`${kv([['引擎狀態',status],['Context',d.context],['作業系統',d.operatingSystem],['容器 OS / 架構',[d.osType,d.architecture].filter(Boolean).join(' / ')],['Kernel',d.kernelVersion],['Engine 版本',d.serverVersion]])}${!online?`<p class="usage-alert">${e(d.status==='remote-context'?'目前 context 指向遠端；未將遠端主機資源列為本機盤點。':unavailable)}</p>`:''}${branch('資源使用量','Images / Containers / Volumes / Build Cache',usageSummary,true)}${branch('Images',online?`${d.images.length} 筆`:'未取得',imageRows.length?resourceTable(['Image / Tag','OS / 架構','Image 大小','ID'],imageRows):note(online?'沒有 Images。':unavailable))}${branch('容器',online?`${d.containers.length} 個`:'未取得',containerRows.length?resourceTable(['名稱','Image','狀態','可寫層 / 虛擬大小'],containerRows):note(online?'沒有容器。':unavailable))}${branch('Volumes',online?`${d.volumes.length} 個`:'未取得',d.volumes.length?resourceTable(['名稱','Driver / Scope','使用空間','引用數'],d.volumes.map(v=>[v.name,[v.driver,v.scope].filter(Boolean).join(' / '),bytes(v.sizeBytes),v.refCount])):note(online?'沒有 Volumes。':unavailable))}${!linuxHost||d.disks.length?branch('Docker Desktop 虛擬磁碟',`${d.disks.length} 個`,disks(d.disks)):''}${d.warnings.length?note(d.warnings.join(' · ')):''}`;
  panel.innerHTML=`<div class="usage-heading"><div><h3>子系統盤點 <span class="usage-inline-label">WSL / DOCKER</span></h3><p>檢視各子系統的作業系統、磁碟占用與 Images。</p></div>${controls(pc,'environments')}</div><div class="usage-last-checked">最後盤點 ${e(time(inventory.capturedAt))} (台北)</div><div class="usage-metrics">${[[linuxHost?'主機 OS':'WSL 發行版',linuxHost?pc.os.name:`${wsl.distributions.length} 個`],['Docker 引擎',status],[linuxHost?'Docker 映像檔占用':'Docker VHD 主機占用',linuxHost?d.summary.find(v=>v.type==='Images')?.size||'未取得':hasDisk?bytes(diskSum):'未取得']].map(([label,value])=>`<div><small>${label}</small><strong>${e(value)}</strong></div>`).join('')}</div>${!linuxHost?branch('WSL 發行版',`${wsl.distributions.length} 個`,wslBody,true):''}${branch('Docker',status,dockerBody,true)}${note('此頁顯示最近一次從該電腦盤點的狀態。Image 大小不等於可回收空間，共用層可能重複計算；VHD 主機占用與 Linux 檔案系統使用量分開列示，不加總重複的 WSL / Docker 磁碟。')}`;
}
